package com.projetok.studio;
import javax.swing.*;
import java.awt.*;
import java.awt.event.*;
import java.nio.file.*;
import java.util.*;

/** Painel de problemas com evidencia e navegacao; revisoes exigem acao explicita. */
final class DiagnosticTools {
    final WorldStudio ui;
    DiagnosticTools(WorldStudio ui){this.ui=ui;ui.action("Diagnostico","Analisar mapas conhecidos",()->analyze(null));ui.action("Diagnostico","Validar arquivo sem abrir",()->{var chooser=new JFileChooser(ui.project.toFile());if(chooser.showOpenDialog(ui)==JFileChooser.APPROVE_OPTION)analyze(chooser.getSelectedFile().toPath());});ui.action("Diagnostico","Aceitar revisao do asset base selecionado",this::review);}
    void analyze(Path file){var maps=ui.maps();var catalog=ui.catalog;ui.status.setText("Analisando referencias e hashes fora da interface...");new SwingWorker<java.util.List<StudioProblem>,Void>(){
        protected java.util.List<StudioProblem> doInBackground(){try{if(file==null)return StudioValidator.validate(maps,catalog,true);var d=DocumentStore.load(file);return StudioValidator.validate(Map.of(d.id(),d),catalog,true);}catch(Exception ex){return java.util.List.of(new StudioProblem(StudioProblem.Severity.ERROR,"arquivo","", "Arquivo de mapa invalido",String.valueOf(ex.getMessage()),"Abra backup integro ou corrija uma copia; arquivo original preservado"));}}
        protected void done(){try{show(get());}catch(Exception ex){ui.error(ex);}}
    }.execute();}
    void show(java.util.List<StudioProblem> problems){JDialog dialog=new JDialog(ui,"Problemas: "+problems.size()+" | duplo clique navega",false);JList<StudioProblem> list=new JList<>(problems.toArray(StudioProblem[]::new));JTextArea detail=new JTextArea(6,80);detail.setEditable(false);detail.setLineWrap(true);detail.setWrapStyleWord(true);list.addListSelectionListener(e->{var p=list.getSelectedValue();if(p!=null)detail.setText(p.severity()+" | "+p.map()+" / "+p.element()+"\n"+p.description()+"\nEvidencia: "+p.evidence()+"\nCorrecao possivel: "+p.correction());});list.addMouseListener(new MouseAdapter(){public void mouseClicked(MouseEvent e){if(e.getClickCount()==2&&list.getSelectedValue()!=null)navigate(list.getSelectedValue());}});JPanel panel=new JPanel(new BorderLayout());panel.add(new JScrollPane(list));panel.add(new JScrollPane(detail),BorderLayout.SOUTH);dialog.setContentPane(panel);dialog.setSize(1000,500);dialog.setLocationRelativeTo(ui);dialog.setVisible(true);ui.status.setText("Diagnostico: "+problems.size()+" problemas; nenhuma correcao automatica");}
    void navigate(StudioProblem p){Runnable action=()->{var d=ui.maps().get(p.map());if(d==null)return;if(!d.id().equals(ui.document.id())){ui.document=ui.history.reset(d);ui.fileTools.file=null;ui.fileTools.saved=null;ui.layerTools.refresh();ui.warmImages();}ui.canvas.selected.clear();ui.canvas.selected.add(p.element());int x=d.width()/2,y=d.height()/2;var element=d.elements().stream().filter(e->e.id().equals(p.element())).findFirst();if(element.isPresent()){x=element.get().x();y=element.get().y();}else{var portal=d.portals().stream().filter(e->e.id().equals(p.element())).findFirst();if(portal.isPresent()){x=portal.get().x();y=portal.get().y();}}ui.canvas.viewport=new StudioViewport(ui.canvas.viewport.zoom(),ui.canvas.getWidth()/2d-x*ui.canvas.viewport.zoom(),ui.canvas.getHeight()/2d-y*ui.canvas.viewport.zoom());ui.canvas.repaint();};if(p.map().equals(ui.document.id()))action.run();else ui.fileTools.confirm(action);}
    void review(){var e=ui.document.elements().stream().filter(a->ui.canvas.selected.contains(a.id())&&!a.asset().isEmpty()).findFirst().orElseThrow(()->new IllegalArgumentException("Selecione elemento com sprite"));EditorOperations.editable(ui.document,e.layer());if(e.locked())throw new IllegalArgumentException("Objeto bloqueado");var asset=ui.catalog.byId().get(e.asset());if(asset==null)throw new IllegalArgumentException("Reindexe a biblioteca primeiro");if((long)e.crop().x()+e.crop().width()>asset.width()||(long)e.crop().y()+e.crop().height()>asset.height())throw new IllegalArgumentException("Recorte nao cabe na nova revisao");if(JOptionPane.showConfirmDialog(ui,"Aceitar somente a revisao base deste elemento?\nAnterior: "+e.sha()+"\nNova: "+asset.sha()+"\nNao representa aprovacao artistica.","Revisao explicita",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;var n=new WorldDocument.Element(e.id(),e.kind(),e.asset(),asset.sha(),e.crop(),e.x(),e.y(),e.width(),e.height(),e.layer(),e.visible(),e.locked(),e.reference(),e.direction(),e.properties());ui.change(ui.document.withElements(ui.document.elements().stream().map(a->a.id().equals(e.id())?n:a).toList()));ui.warmImages();}
}
